export async function handleReceiptEvent(event, dependencies) {
  throw new Error('Implement the Pub/Sub handler');
}

import assert from 'node:assert/strict';
import { handleReceiptEvent } from './handler.js';

const processed = new Set();
const receipts = [];
const dependencies = { processed, receipts: { async create(value) { receipts.push(value); } } };
const payload = Buffer.from(JSON.stringify({ orderId: 'ord-42', email: 'buyer@example.com' })).toString('base64');
const event = { id: 'evt-42', data: { message: { data: payload } } };
assert.deepEqual(await handleReceiptEvent(event, dependencies), { duplicate: false });
assert.equal(receipts.length, 1);
assert.equal(receipts[0].orderId, 'ord-42');
assert.deepEqual(await handleReceiptEvent(event, dependencies), { duplicate: true });
assert.equal(receipts.length, 1);
await assert.rejects(() => handleReceiptEvent({ data: {} }, dependencies), /event id|message data/i);
console.log('6 assertions passed');
